import java.util.ArrayList;
import java.util.List;

class VideoSharingPlatform {
    private static class Video {
        String content;
        int views;
        int likes;
        int dislikes;
        Video(String content) {
            this.content = content;
        }
    }

    private final List<Video> slots = new ArrayList<>();

    public VideoSharingPlatform() {}

    public int upload(String video) {
        for (int id = 0; id < slots.size(); id++) {
            if (slots.get(id) == null) {
                slots.set(id, new Video(video));
                return id;
            }
        }
        slots.add(new Video(video));
        return slots.size() - 1;
    }

    public void remove(int videoId) {
        if (isActive(videoId)) {
            slots.set(videoId, null);
        }
    }

    public String watch(int videoId, int startMinute, int endMinute) {
        if (!isActive(videoId)) {
            return "-1";
        }
        Video video = slots.get(videoId);
        video.views++;
        return video.content.substring(startMinute, Math.min(endMinute + 1, video.content.length()));
    }

    public void like(int videoId) {
        if (isActive(videoId)) {
            slots.get(videoId).likes++;
        }
    }

    public void dislike(int videoId) {
        if (isActive(videoId)) {
            slots.get(videoId).dislikes++;
        }
    }

    public int[] getLikesAndDislikes(int videoId) {
        if (!isActive(videoId)) {
            return new int[]{-1};
        }
        Video video = slots.get(videoId);
        return new int[]{video.likes, video.dislikes};
    }

    public int getViews(int videoId) {
        return isActive(videoId) ? slots.get(videoId).views : -1;
    }

    private boolean isActive(int videoId) {
        return 0 <= videoId && videoId < slots.size() && slots.get(videoId) != null;
    }
}

