import java.util.HashMap;
import java.util.Map;

class VideoSharingPlatform {
    private static class Video {
        String content;
        int views;
        int likes;
        int dislikes;
        Video(String content) {
            this.content = content;
        }
    }

    private final Map<Integer, Video> videos = new HashMap<>();
    private int[] heap = new int[16];
    private int heapSize = 0;
    private int nextId = 0;

    public VideoSharingPlatform() {}

    public int upload(String video) {
        int id = heapSize == 0 ? nextId++ : pollFreeId();
        videos.put(id, new Video(video));
        return id;
    }

    public void remove(int videoId) {
        if (videos.remove(videoId) != null) {
            offerFreeId(videoId);
        }
    }

    public String watch(int videoId, int startMinute, int endMinute) {
        Video video = videos.get(videoId);
        if (video == null) {
            return "-1";
        }
        video.views++;
        return video.content.substring(startMinute, Math.min(endMinute + 1, video.content.length()));
    }

    public void like(int videoId) {
        Video video = videos.get(videoId);
        if (video != null) {
            video.likes++;
        }
    }

    public void dislike(int videoId) {
        Video video = videos.get(videoId);
        if (video != null) {
            video.dislikes++;
        }
    }

    public int[] getLikesAndDislikes(int videoId) {
        Video video = videos.get(videoId);
        return video == null ? new int[]{-1} : new int[]{video.likes, video.dislikes};
    }

    public int getViews(int videoId) {
        Video video = videos.get(videoId);
        return video == null ? -1 : video.views;
    }

    private void offerFreeId(int value) {
        if (heapSize == heap.length) {
            int[] next = new int[heap.length * 2];
            System.arraycopy(heap, 0, next, 0, heap.length);
            heap = next;
        }
        heap[heapSize] = value;
        siftUp(heapSize++);
    }

    private int pollFreeId() {
        int result = heap[0];
        heap[0] = heap[--heapSize];
        siftDown(0);
        return result;
    }

    private void siftUp(int index) {
        while (index > 0) {
            int parent = (index - 1) / 2;
            if (heap[parent] <= heap[index]) {
                break;
            }
            swap(parent, index);
            index = parent;
        }
    }

    private void siftDown(int index) {
        while (true) {
            int left = index * 2 + 1;
            int right = left + 1;
            int smallest = index;
            if (left < heapSize && heap[left] < heap[smallest]) {
                smallest = left;
            }
            if (right < heapSize && heap[right] < heap[smallest]) {
                smallest = right;
            }
            if (smallest == index) {
                return;
            }
            swap(index, smallest);
            index = smallest;
        }
    }

    private void swap(int a, int b) {
        int temp = heap[a];
        heap[a] = heap[b];
        heap[b] = temp;
    }
}
